body:
This PR fixes issue #25647.

Table in-out functions can advertise filter and projection pushdown, but the physical table in-out operator did not pass the generated `TableFilterSet` or projection IDs to `init_global` and `init_local`. Filters removed from the logical plan could therefore be silently skipped, producing incorrect results.

This PR:

1. forwards pushed filters and projection IDs to table in-out initialization;
2. keeps type-selective pushdown conservative, without changing partial or correlated-filter semantics;
3. retains filters above functions using `WITH ORDINALITY`, so surviving rows preserve their original ordinal positions;
4. remaps the ordinality column correctly after projection pruning.

The tests cover filter delivery to global and local initialization, filter-only columns, `filter_prune = false`, type-limited and correlated filters, lateral projection mapping, and `WITH ORDINALITY` behavior.

### What happens?

`duckdb_v2_arrow_importer_*` doesnt read the validity buffer of *top-level* array handed to through the Arrow C Data Interface. 

That array is a struct (one child per column), and the spec permits it to carry its own `buffers[0]` / `null_count` like any other array. When it does,
every row still imports as non-null, whatever the bitmap says. 

No error, no crash: just wrong data.

In practice this is not reachable through `pa.Table` or `pl.DataFrame`'s own `__arrow_c_stream__`, since those always export plain record batches whose top-level struct has `buffers[0] == NULL` by construction. But, by the spec, it's allowed and would cause an error. 

At minimum, a check and hard failure if a validity buffer is provided would be a good immediate safety fix. 


### Spec
https://arrow.apache.org/docs/format/CDataInterface.html


### To Reproduce

##  `test/api/capi/v2/test_capi_v2_arrow.cpp` test case

exports a 16-row BIGINT column through the existing exporter/importer round-trip, then substitutes a wrapper around the exporter's own top-level array whose `buffers[0]` and `null_count` mark rows 1, 2 and 9 null.

Re-imports through the same importer and asserts those three rows come back `NULL`.

* It fails on the first of the three rows, and the message carries what was returned instead:

```
test/api/capi/v2/test_capi_v2_arrow.cpp:951: FAILED:
  REQUIRE( arrow_toplevel_validity_observed.valid[i] == !expect_null )
with expansion:
  1 == false
with message:
  row 1 value 1
```


```diff
diff --git a/test/api/capi/v2/test_capi_v2_arrow.cpp b/test/api/capi/v2/test_capi_v2_arrow.cpp
index afb13505e6..5bd369761a 100644
--- a/test/api/capi/v2/test_capi_v2_arrow.cpp
+++ b/test/api/capi/v2/test_capi_v2_arrow.cpp
@@ -584,6 +584,116 @@ void RunArrowProbe(duckdb_v2_connection_handle conn, const char *sql) {
 	duckdb_v2_result_destroy(&r);
 }

+struct TopLevelValidityObserved {
+	std::vector<int64_t> values;
+	std::vector<bool> valid;
+	DUCKDB_V2_ERROR append_rc = DUCKDB_V2_ERROR_NONE;
+};
+TopLevelValidityObserved arrow_toplevel_validity_observed;
+
+void ArrowTopLevelValidityReleaseArray(ArrowArray *array) {
+	array->release = nullptr; // children are borrowed from the exporter's own array
+}
+
+// Exports one BIGINT column of 16 rows, then hands importer a wrapper around exporter's
+// own top-level array, carrying validity bitmap marking rows 1, 2 and 9 null. The
+// exporter never sets buffers[0] on top-level array, but  Arrow C Data Interface
+// spec allows producer of top-level struct array to do so
+void ArrowTopLevelValidityExec(duckdb_v2_scalar_function_exec_info_handle info, duckdb_v2_context_handle context,
+                               duckdb_v2_error_info_handle *err) {
+	arrow_toplevel_validity_observed = {};
+	duckdb_v2_vector_handle result = nullptr;
+	if (duckdb_v2_scalar_function_exec_get_result(info, &result, err) != DUCKDB_V2_ERROR_NONE) {
+		return;
+	}
+	auto bigint = ArrowTypeInCallback(context, DUCKDB_V2_LOGICAL_TYPE_ID_BIGINT, err);
+	if (!bigint) {
+		return;
+	}
+	auto column = Convert("i");
+	auto *rt = ArrowMakeRoundtrip(context, &bigint, &column, 1, 0, 0, err);
+	if (!rt) {
+		duckdb_v2_logical_type_destroy(&bigint);
+		return;
+	}
+
+	constexpr idx_t rows = 16;
+	duckdb_v2_data_chunk_handle input = nullptr;
+	auto rc = duckdb_v2_data_chunk_create(&bigint, 1, &input, err);
+	duckdb_v2_logical_type_destroy(&bigint);
+	if (rc != DUCKDB_V2_ERROR_NONE) {
+		ArrowRoundtripDestroy(rt);
+		return;
+	}
+	duckdb_v2_vector_handle in_v = nullptr;
+	void *data = nullptr;
+	if (duckdb_v2_data_chunk_get_vector(input, 0, &in_v, err) == DUCKDB_V2_ERROR_NONE &&
+	    duckdb_v2_vector_get_data_mutable(in_v, &data, err) == DUCKDB_V2_ERROR_NONE) {
+		for (idx_t i = 0; i < rows; i++) {
+			static_cast<int64_t *>(data)[i] = static_cast<int64_t>(i);
+		}
+		duckdb_v2_vector_set_size(in_v, rows, err);
+	}
+
+	auto borrowed = input;
+	if (duckdb_v2_arrow_exporter_append(rt->exporter, &borrowed, false, true, err) != DUCKDB_V2_ERROR_NONE) {
+		duckdb_v2_data_chunk_destroy(&input);
+		ArrowRoundtripDestroy(rt);
+		return;
+	}
+	ArrowArray real_array {};
+	if (duckdb_v2_arrow_exporter_next_array(rt->exporter, &real_array, err) != DUCKDB_V2_ERROR_NONE ||
+	    !real_array.release) {
+		duckdb_v2_data_chunk_destroy(&input);
+		ArrowRoundtripDestroy(rt);
+		return;
+	}
+
+	// Rows 1, 2 and 9 null (bit clear == null); the rest valid. Arrow validity bitmap, 
+	// legal for any producer to hand a
+	// consumer.
+	uint8_t mask[2] = {0xF9, 0xFD};
+	const void *wrapped_buffers[1] = {mask};
+	ArrowArray wrapped_array {};
+	wrapped_array.length = real_array.length;
+	wrapped_array.null_count = 3;
+	wrapped_array.offset = 0;
+	wrapped_array.n_buffers = 1;
+	wrapped_array.n_children = real_array.n_children;
+	wrapped_array.buffers = wrapped_buffers;
+	wrapped_array.children = real_array.children;
+	wrapped_array.release = ArrowTopLevelValidityReleaseArray;
+
+	arrow_toplevel_validity_observed.append_rc =
+	    duckdb_v2_arrow_importer_append(rt->importer, &wrapped_array, false, true, err);
+	if (arrow_toplevel_validity_observed.append_rc == DUCKDB_V2_ERROR_NONE) {
+		duckdb_v2_data_chunk_handle imported = nullptr;
+		if (duckdb_v2_arrow_importer_next_chunk(rt->importer, &imported, err) == DUCKDB_V2_ERROR_NONE && imported) {
+			duckdb_v2_vector_handle out_v = nullptr;
+			duckdb_v2_vector_view view {};
+			if (duckdb_v2_data_chunk_get_vector(imported, 0, &out_v, err) == DUCKDB_V2_ERROR_NONE &&
+			    duckdb_v2_vector_get_view(out_v, &view, err) == DUCKDB_V2_ERROR_NONE) {
+				for (idx_t i = 0; i < rows; i++) {
+					auto idx = SelAt(view.sel, i);
+					arrow_toplevel_validity_observed.values.push_back(
+					    reinterpret_cast<const int64_t *>(view.data)[idx]);
+					arrow_toplevel_validity_observed.valid.push_back(RowValid(view, idx));
+				}
+			}
+			duckdb_v2_data_chunk_destroy(&imported);
+		}
+	}
+	real_array.release(&real_array);
+
+	duckdb_v2_data_chunk_destroy(&input);
+	ArrowRoundtripDestroy(rt);
+	int32_t one = 1;
+	void *out = nullptr;
+	if (duckdb_v2_vector_get_data_mutable(result, &out, err) == DUCKDB_V2_ERROR_NONE) {
+		std::memcpy(out, &one, sizeof(one));
+	}
+}
+
 } // namespace

 // ===========================================================================
@@ -827,6 +937,21 @@ TEST_CASE("V2 arrow: a batch size caps the output in both directions", "[capi_v2
 	}
 }

+TEST_CASE("V2 arrow: a top-level struct array's own validity bitmap is honored", "[capi_v2][arrow]") {
+	EnvFixture fx;
+	RegisterArrowProbe(fx.conn, "arrow_toplevel_validity_probe", ArrowTopLevelValidityExec);
+	RunArrowProbe(fx.conn, "SELECT arrow_toplevel_validity_probe(1)");
+
+	REQUIRE(arrow_toplevel_validity_observed.append_rc == DUCKDB_V2_ERROR_NONE);
+	REQUIRE(arrow_toplevel_validity_observed.valid.size() == 16);
+	// Rows 1, 2 and 9 were marked null in the wrapper's own validity buffer; the rest were not.
+	for (idx_t i = 0; i < 16; i++) {
+		bool expect_null = (i == 1 || i == 2 || i == 9);
+		INFO("row " << i << " value " << arrow_toplevel_validity_observed.values[i]);
+		REQUIRE(arrow_toplevel_validity_observed.valid[i] == !expect_null);
+	}
+}
+
 TEST_CASE("V2 arrow: the exporter accepts input without draining first", "[capi_v2][arrow]") {
 	EnvFixture fx;
 	RegisterArrowProbe(fx.conn, "arrow_split_probe", ArrowSplitExec);
```


